import type { HTMLAttributes, ReactNode } from "react";
import { cx } from "../utils/cx";

/** A row of key figures divided by hairlines (stacks on phones). Renders a <dl>. */
export function StatGroup({ className, ...rest }: HTMLAttributes<HTMLDListElement>) {
  return <dl {...rest} className={cx("hm-stat-group", className)} />;
}

export type StatProps = Omit<HTMLAttributes<HTMLDivElement>, "children"> & {
  label: ReactNode;
  value: ReactNode;
  /** One line of context under the figure ("Up 12% on the 30 days before"). */
  detail?: ReactNode;
  /** Colors the detail: `up` is good news, `down` bad, `neutral` (default) informational. */
  trend?: "up" | "down" | "neutral";
};

export function Stat({ label, value, detail, trend = "neutral", className, ...rest }: StatProps) {
  return (
    <div {...rest} className={cx("hm-stat", className)}>
      <dt className="hm-stat-label">{label}</dt>
      <dd className="hm-stat-value">{value}</dd>
      {detail ? (
        <dd className="hm-stat-detail" data-trend={trend}>
          {detail}
        </dd>
      ) : null}
    </div>
  );
}
